import { EventEmitter } from 'events';

interface TikTokUser {
    id: string;
    nickname: string;
    uniqueId: string;
    profilePicture?: string;
    /** High-resolution avatar URL from protobuf field 11 (avatarLarge ~720x720) */
    avatarLargeUrl?: string;
    badges?: string[];
}
interface BaseEvent {
    type: string;
    timestamp: number;
    msgId: string;
}
interface ChatEvent extends BaseEvent {
    type: 'chat';
    user: TikTokUser;
    comment: string;
    emotes?: Array<{
        emoteId: string;
        imageUrl: string;
        placeInComment: number;
    }>;
}
interface MemberEvent extends BaseEvent {
    type: 'member';
    user: TikTokUser;
    action: number;
}
interface LikeEvent extends BaseEvent {
    type: 'like';
    user: TikTokUser;
    likeCount: number;
    totalLikes: number;
}
interface GiftEvent extends BaseEvent {
    type: 'gift';
    user: TikTokUser;
    giftId: number;
    giftName: string;
    diamondCount: number;
    repeatCount: number;
    repeatEnd: boolean;
    combo: boolean;
    giftType: number;
    groupId: string;
}
interface SocialEvent extends BaseEvent {
    type: 'social';
    user: TikTokUser;
    action: 'follow' | 'share' | string;
}
interface RoomUserSeqEvent extends BaseEvent {
    type: 'roomUserSeq';
    viewerCount: number;
    totalViewers: number;
}
interface BattleTeamUser {
    user: TikTokUser;
    score: number;
}
interface BattleTeam {
    hostUserId: string;
    hostUser?: TikTokUser;
    score: number;
    users: BattleTeamUser[];
}
interface BattleEvent extends BaseEvent {
    type: 'battle';
    battleId: string;
    status: number;
    battleDuration: number;
    teams: BattleTeam[];
}
interface BattleArmiesEvent extends BaseEvent {
    type: 'battleArmies';
    battleId: string;
    status: number;
    teams: BattleTeam[];
    /** Battle start timestamp in milliseconds (from f18.f2) */
    battleStartMs: number;
    /** Total battle duration in seconds (from f18.f3, typically 300) */
    battleDurationSeconds: number;
    /** Seconds remaining in the battle, computed as max(0, duration - elapsed). Note: uses VPS clock, may be off by up to 30s */
    timeLeftSeconds: number;
    /** Battle end timestamp in milliseconds (battleStartMs + duration*1000). Use for clock-independent timer: Math.max(0, (endTimeMs - Date.now()) / 1000) */
    endTimeMs: number;
}
interface SubscribeEvent extends BaseEvent {
    type: 'subscribe';
    user: TikTokUser;
    subMonth: number;
}
interface EmoteChatEvent extends BaseEvent {
    type: 'emoteChat';
    user: TikTokUser;
    emoteId: string;
    emoteUrl: string;
}
interface EnvelopeEvent extends BaseEvent {
    type: 'envelope';
    envelopeId: string;
    diamondCount: number;
}
interface QuestionEvent extends BaseEvent {
    type: 'question';
    user: TikTokUser;
    questionText: string;
}
interface ControlEvent extends BaseEvent {
    type: 'control';
    action: number;
}
interface RoomEvent extends BaseEvent {
    type: 'room';
    status: number;
}
interface LiveIntroEvent extends BaseEvent {
    type: 'liveIntro';
    roomId: string;
    title: string;
}
interface RankUpdateEvent extends BaseEvent {
    type: 'rankUpdate';
    rankType: string;
    rankList: Array<{
        user: TikTokUser;
        rank: number;
        score: number;
    }>;
}
interface LinkMicEvent extends BaseEvent {
    type: 'linkMic';
    action: string;
    users: TikTokUser[];
}
interface UnknownEvent extends BaseEvent {
    type: 'unknown';
    method: string;
}
type LiveEvent = ChatEvent | MemberEvent | LikeEvent | GiftEvent | SocialEvent | RoomUserSeqEvent | BattleEvent | BattleArmiesEvent | SubscribeEvent | EmoteChatEvent | EnvelopeEvent | QuestionEvent | ControlEvent | RoomEvent | LiveIntroEvent | RankUpdateEvent | LinkMicEvent | UnknownEvent;
interface TikTokLiveEvents {
    connected: () => void;
    disconnected: (code: number, reason: string) => void;
    roomInfo: (info: RoomInfo) => void;
    error: (error: Error) => void;
    chat: (event: ChatEvent) => void;
    member: (event: MemberEvent) => void;
    like: (event: LikeEvent) => void;
    gift: (event: GiftEvent) => void;
    social: (event: SocialEvent) => void;
    roomUserSeq: (event: RoomUserSeqEvent) => void;
    battle: (event: BattleEvent) => void;
    battleArmies: (event: BattleArmiesEvent) => void;
    subscribe: (event: SubscribeEvent) => void;
    emoteChat: (event: EmoteChatEvent) => void;
    envelope: (event: EnvelopeEvent) => void;
    question: (event: QuestionEvent) => void;
    control: (event: ControlEvent) => void;
    room: (event: RoomEvent) => void;
    liveIntro: (event: LiveIntroEvent) => void;
    rankUpdate: (event: RankUpdateEvent) => void;
    linkMic: (event: LinkMicEvent) => void;
    unknown: (event: UnknownEvent) => void;
    event: (event: LiveEvent) => void;
}
interface RoomInfo {
    roomId: string;
    wsHost: string;
    clusterRegion: string;
    connectedAt: string;
}
/** Quality tiers available for live stream video */
type StreamQuality = 'FULL_HD1' | 'HD1' | 'SD1' | 'SD2' | 'origin' | string;
/** Stream URLs for a specific quality level */
interface StreamUrls {
    /** FLV pull URL for this quality */
    flv?: string;
    /** HLS (m3u8) pull URL for this quality */
    hls?: string;
}
/** Full stream info returned by getStreamUrl() */
interface StreamInfo {
    /** Room ID of the live stream */
    roomId: string;
    /** Whether the user is currently live */
    alive: boolean;
    /** Stream URLs keyed by quality (FULL_HD1, HD1, SD1, SD2) */
    streamUrls: Record<StreamQuality, StreamUrls>;
    /** Recommended default quality */
    defaultQuality: StreamQuality;
    /** Best available FLV URL (convenience shortcut) */
    flvPullUrl?: string;
    /** Best available HLS URL (convenience shortcut) */
    hlsPullUrl?: string;
}
interface TikTokLiveOptions {
    uniqueId: string;
    signServerUrl?: string;
    apiKey: string;
    autoReconnect?: boolean;
    maxReconnectAttempts?: number;
    heartbeatInterval?: number;
    debug?: boolean;
    /** Pre-resolved room ID — skips direct TikTok page fetch when provided with sessionId */
    roomId?: string;
    /** Pre-resolved ttwid session cookie — skips direct TikTok page fetch when provided with roomId */
    sessionId?: string;
}

declare class TikTokLive extends EventEmitter {
    private ws;
    private heartbeatTimer;
    private reconnectAttempts;
    private intentionalClose;
    private _connected;
    private _destroyed;
    private _eventCount;
    private _roomId;
    private static readonly MAX_BATTLE_HOSTS;
    private _battleHosts;
    private _pendingHostResolves;
    private readonly uniqueId;
    private readonly signServerUrl;
    private readonly apiKey;
    private readonly autoReconnect;
    private readonly maxReconnectAttempts;
    private readonly heartbeatInterval;
    private readonly debug;
    private readonly _presetRoomId;
    private readonly _presetSessionId;
    constructor(options: TikTokLiveOptions);
    connect(): Promise<void>;
    disconnect(): void;
    /**
     * Fully destroy the client, releasing all resources and listeners.
     * After calling destroy(), the instance cannot be reused — create a new one.
     */
    destroy(): void;
    get connected(): boolean;
    get destroyed(): boolean;
    get eventCount(): number;
    get roomId(): string;
    /**
     * Get live stream video URLs for a TikTok user.
     * Returns FLV & HLS URLs segmented by quality (FULL_HD1, HD1, SD1, SD2).
     * This is a standalone method — no WebSocket connection required.
     *
     * @example
     * ```ts
     * const stream = await TikTokLive.getStreamUrl({
     *   uniqueId: 'username',
     *   apiKey: 'your-api-key',
     * });
     * if (stream.alive) {
     *   console.log(stream.streamUrls.HD1?.hls); // HLS URL for HD quality
     *   console.log(stream.flvPullUrl);           // Best FLV URL
     * }
     * ```
     */
    static getStreamUrl(options: {
        uniqueId: string;
        apiKey: string;
        signServerUrl?: string;
        quality?: string;
    }): Promise<StreamInfo>;
    on<K extends keyof TikTokLiveEvents>(event: K, listener: TikTokLiveEvents[K]): this;
    once<K extends keyof TikTokLiveEvents>(event: K, listener: TikTokLiveEvents[K]): this;
    off<K extends keyof TikTokLiveEvents>(event: K, listener: TikTokLiveEvents[K]): this;
    emit<K extends keyof TikTokLiveEvents>(event: K, ...args: Parameters<TikTokLiveEvents[K]>): boolean;
    private handleFrame;
    /**
     * Resolve unknown host user IDs via the sign server API.
     * Caches results and re-emits the battleArmies event with enriched hostUser data.
     */
    private resolveHostUsers;
    private startHeartbeat;
    private stopHeartbeat;
}

export { type BaseEvent, type BattleArmiesEvent, type BattleEvent, type BattleTeam, type BattleTeamUser, type ChatEvent, type ControlEvent, type EmoteChatEvent, type EnvelopeEvent, type GiftEvent, type LikeEvent, type LinkMicEvent, type LiveEvent, type LiveIntroEvent, type MemberEvent, type QuestionEvent, type RankUpdateEvent, type RoomEvent, type RoomInfo, type RoomUserSeqEvent, type SocialEvent, type StreamInfo, type StreamQuality, type StreamUrls, type SubscribeEvent, TikTokLive, type TikTokLiveEvents, type TikTokLiveOptions, type TikTokUser, type UnknownEvent };
